g.script:
var H = SVGAnim.Helpers, NS = H.SVG_NS;
var KF = SVGAnim.Keyframe;
var IMAGEM = '../mapa brasil 1.jpg';
var CENTRO_X = 400, CENTRO_Y = 250;
var T_BAR_X = 40, T_BAR_W = 720;

var camada = H.get('camadaZoom'), imagem = H.get('imgMapa');
var statusText = H.get('statusText'), statusBg = H.get('statusBg');
var btnPlay = H.get('btnPlay'), progressBar = H.get('progressBar');
var kfInfo = H.get('kfInfo');
var kfContainer = H.get('kfContainer'), kfLabelContainer = H.get('kfLabelContainer');
var durLabel = H.get('durLabel');
imagem.style.transformOrigin = '400px 250px';

var camera = new SVGAnim.Camera({
  zoom: 1.0, blur: 7, blurFilterId: 'blurElem',
  rotationX: -25, rotationY: 15, rotationZ: 0,
  tx: 0, ty: 0, perspective: 800,
  zoomCenterX: CENTRO_X, zoomCenterY: CENTRO_Y
});

var keyframes = [
  new KF({ tempo: 0,  zoom: 1.0, blur: 7,  rotationX: -25, rotationY: 15 }),
  new KF({ tempo: 5,  zoom: 1.5, blur: 0,  rotationX: 0,   rotationY: 0 })
];
var kfIdx = 0;
var rodando = false, modoExibicao = false;
var zoomEnabled = true, blurEnabled = true, rotEnabled = true, translEnabled = true;
var highlighter = new SVGAnim.Highlighter();
var canetaAtiva = false;
var canetaThickness = 5;
var canetaColor = '#FFFF00';
var canetaOpacity = 0.4;
var modoBorracha = false;
var marcacaoAtiva = false;
var cameraSaved = null;
var restaurando = false;

function aplicarTransformacao() {
  camada.style.transform = camera.getCameraTransform();
  camada.style.transformOrigin = '0 0';
  imagem.style.transform = camera.getImage3DTransform();
}

function entrarModoMarcacao() {
  if (marcacaoAtiva) return;
  marcacaoAtiva = true;
  cameraSaved = {
    zoom: camera.zoom, blur: camera.blur,
    rotationX: camera.rotationX, rotationY: camera.rotationY, rotationZ: camera.rotationZ,
    tx: camera.tx, ty: camera.ty, perspective: camera.perspective
  };
  camera.zoom = 1; camera.blur = 0; camera.tx = 0; camera.ty = 0;
  camera.rotationX = 0; camera.rotationY = 0; camera.rotationZ = 0;
  if (camera.blurFilterId) { var f = document.getElementById(camera.blurFilterId); if (f) f.setAttribute('stdDeviation', '0'); }
  aplicarTransformacao();
  atualizarHighlights(keyframes[kfIdx].tempo);
  g('panelHandle').setAttribute('display', 'inline');
  H.get('overlayMouse').style.cursor = 'none';
}

function sairModoMarcacao() {
  if (!marcacaoAtiva || !cameraSaved) return;
  if (imagemNaFrente) toggleCamadas();
  H.get('overlayMouse').style.cursor = '';
  g('panelHandle').setAttribute('display', 'none');
  g('penCursor').setAttribute('display', 'none');
  marcacaoAtiva = false;
  camera.zoom = cameraSaved.zoom; camera.blur = cameraSaved.blur;
  camera.tx = cameraSaved.tx; camera.ty = cameraSaved.ty;
  camera.rotationX = cameraSaved.rotationX; camera.rotationY = cameraSaved.rotationY; camera.rotationZ = cameraSaved.rotationZ;
  camera.perspective = cameraSaved.perspective;
  if (camera.blurFilterId) { var f = document.getElementById(camera.blurFilterId); if (f) f.setAttribute('stdDeviation', camera.blur); }
  cameraSaved = null;
  aplicarTransformacao();
  aplicarKeyframeNaCamera(keyframes[kfIdx]);
  atualizarHighlights(keyframes[kfIdx].tempo);
  atualizarStatus();
}

var imagemNaFrente = false;

function toggleCamadas() {
  imagemNaFrente = !imagemNaFrente;
  var svg = H.get('svgRaiz');
  var cz = H.get('camadaZoom');
  var tb = H.get('toolbars');
  var me = H.get('modoExibicao');
  if (imagemNaFrente) {
    svg.appendChild(cz);
    svg.appendChild(H.get('lbTop'));
    svg.appendChild(H.get('lbBot'));
    svg.appendChild(H.get('lbLeft'));
    svg.appendChild(H.get('lbRight'));
    svg.appendChild(H.get('guideTop'));
    svg.appendChild(H.get('guideBot'));
    svg.appendChild(H.get('guideLeft'));
    svg.appendChild(H.get('guideRight'));
    svg.appendChild(me);
  } else {
    svg.appendChild(tb);
    svg.insertBefore(me, tb);
  }
}

var resolucao = 'full';
var timeline = new SVGAnim.Timeline({
  duracao: 10, keyframes: keyframes, durLabel: durLabel, progressBar: progressBar
});
var inicioTimestamp = null;
var pausadoMs = 0;

function aplicarLetterbox(opac) {
  if (opac === undefined) opac = rodando ? 1 : 0.4;
  var guideOp = opac === 1 ? 0 : 1;

  g('lbTop').setAttribute('height', '10000'); g('lbTop').setAttribute('opacity', opac);
  g('lbBot').setAttribute('y', '500'); g('lbBot').setAttribute('height', '10000'); g('lbBot').setAttribute('opacity', opac);
  g('lbLeft').setAttribute('width', '10000'); g('lbLeft').setAttribute('opacity', opac);
  g('lbRight').setAttribute('x', '800'); g('lbRight').setAttribute('width', '10000'); g('lbRight').setAttribute('opacity', opac);

  g('guideTop').setAttribute('opacity', 0);
  g('guideBot').setAttribute('opacity', 0);
  g('guideLeft').setAttribute('opacity', 0);
  g('guideRight').setAttribute('opacity', 0);

  if (resolucao === 'youtube') {
    var hYT = 800 * 9 / 16;
    var tm = (500 - hYT) / 2;
    g('lbTop').setAttribute('height', String(10000 + tm));
    g('lbBot').setAttribute('y', String(tm + hYT));
    g('guideTop').setAttribute('y1', String(tm)); g('guideTop').setAttribute('y2', String(tm));
    g('guideBot').setAttribute('y1', String(tm + hYT)); g('guideBot').setAttribute('y2', String(tm + hYT));
    g('guideTop').setAttribute('opacity', guideOp);
    g('guideBot').setAttribute('opacity', guideOp);
  } else if (resolucao === 'instagram') {
    var w = Math.floor(500 * 9 / 18);
    var lm = Math.floor((800 - w) / 2);
    var rm = 800 - lm;
    g('lbLeft').setAttribute('width', String(10000 + lm));
    g('lbRight').setAttribute('x', String(rm));
    g('guideLeft').setAttribute('x1', String(lm)); g('guideLeft').setAttribute('x2', String(lm));
    g('guideRight').setAttribute('x1', String(rm)); g('guideRight').setAttribute('x2', String(rm));
    g('guideLeft').setAttribute('opacity', guideOp);
    g('guideRight').setAttribute('opacity', guideOp);
  }
}

function pausar() {
  rodando = false;
  aplicarLetterbox();
  if (inicioTimestamp !== null) { pausadoMs += performance.now() - inicioTimestamp; inicioTimestamp = null; }
  g('playLabel').textContent = '\u25B6';
  statusBg.setAttribute('fill', 'rgba(0,0,0,0.55)');
  statusText.textContent = 'Pausado — pressione ▶ PLAY para continuar';
  if (modoExibicao) { H.get('toolbars').setAttribute('display', 'inline'); H.get('modoExibicao').setAttribute('display', 'inline'); }
}

var draggingKF = false, dragKFIndex = -1, dragAnchorTime = 0, dragAnchorX = 0;
var arrastando = false, mouseIniX = 0, mouseIniY = 0, txAnchor = 0, tyAnchor = 0;
var drawingPath = '', drawingPoints = [];
var draggingPanel = false;
var panelAnchorY = 0;

function g(id) { return document.getElementById(id); }

var penCursorEl = null;

function atualizarPenCursorColor() {
  if (!penCursorEl) penCursorEl = document.getElementById('penCursor');
  if (!penCursorEl) return;
  var c = canetaColor, op = canetaOpacity;
  var r = parseInt(c.slice(1,3), 16), g = parseInt(c.slice(3,5), 16), b = parseInt(c.slice(5,7), 16);
  var fill = 'rgba(' + r + ',' + g + ',' + b + ',' + (op * 0.6) + ')';
  var stroke = 'rgba(' + r + ',' + g + ',' + b + ',' + op + ')';
  if (modoBorracha) { fill = 'rgba(255,0,0,0.3)'; stroke = '#F44336'; }
  penCursorEl.setAttribute('fill', fill);
  penCursorEl.setAttribute('stroke', stroke);
}

function corCanetaRGBA(op) {
  var c = canetaColor, opacity = op !== undefined ? op : canetaOpacity;
  var r = parseInt(c.slice(1,3), 16), g = parseInt(c.slice(3,5), 16), b = parseInt(c.slice(5,7), 16);
  return 'rgba(' + r + ',' + g + ',' + b + ',' + opacity + ')';
}

/* ====== DOM DO KEYFRAME ====== */

function criarKeyframeDOM(i) {
  var kf = keyframes[i], px = timeline.kfToScreenX(kf.tempo);
  px = Math.max(T_BAR_X, Math.min(T_BAR_X + T_BAR_W, px));
  var sel = (i === kfIdx);

  var g = document.createElementNS(NS, 'g');
  g.setAttribute('id', 'kf-g-' + i);
  g.style.cursor = 'pointer';

  var outer = document.createElementNS(NS, 'circle');
  outer.setAttribute('cx', px); outer.setAttribute('cy', '326');
  outer.setAttribute('r', '8'); outer.setAttribute('fill', '#333');
  outer.setAttribute('stroke', '#aaa'); outer.setAttribute('stroke-width', '2');
  g.appendChild(outer);

  var inner = document.createElementNS(NS, 'circle');
  inner.setAttribute('cx', px); inner.setAttribute('cy', '326');
  inner.setAttribute('r', '3'); inner.setAttribute('fill', '#4CAF50');
  inner.setAttribute('display', 'none');
  g.appendChild(inner);

  if (sel) {
    outer.setAttribute('stroke', '#4CAF50'); outer.setAttribute('stroke-width', '2.5');
    inner.setAttribute('display', 'inline');
  }

  g.addEventListener('mousedown', function(e) {
    if (rodando) return;
    e.stopPropagation();
    kfIdx = i;
    carregarSlidersDoKeyframe(keyframes[i]);
    atualizarSelecaoKeyframes();
    aplicarValoresAtuais();
    if (i > 0) { draggingKF = true; dragKFIndex = i; dragAnchorTime = keyframes[i].tempo; dragAnchorX = e.clientX; }
  });

  kfContainer.appendChild(g);

  var lbl = document.createElementNS(NS, 'text');
  lbl.setAttribute('id', 'kf-lbl-' + i);
  lbl.setAttribute('x', px); lbl.setAttribute('y', '355');
  lbl.setAttribute('font-family', 'Arial, sans-serif');
  lbl.setAttribute('font-size', '9'); lbl.setAttribute('fill', '#999');
  lbl.setAttribute('text-anchor', 'middle');
  lbl.textContent = (i === 0 ? '0.0s' : kf.tempo.toFixed(1) + 's');
  kfLabelContainer.appendChild(lbl);
}

function moverKeyframeDOM(i, px) {
  var grp = g('kf-g-' + i); if (!grp) return;
  px = Math.max(T_BAR_X, Math.min(T_BAR_X + T_BAR_W, px));
  grp.children[0].setAttribute('cx', px);
  grp.children[1].setAttribute('cx', px);
  var lbl = g('kf-lbl-' + i); if (lbl) lbl.setAttribute('x', px);
}

function removerKeyframeDOM(i) {
  var grp = g('kf-g-' + i); if (grp) grp.parentNode.removeChild(grp);
  var lbl = g('kf-lbl-' + i); if (lbl) lbl.parentNode.removeChild(lbl);
}

function atualizarSelecaoKeyframes() {
  for (var i = 0; i < keyframes.length; i++) {
    var grp = g('kf-g-' + i); if (!grp) { criarKeyframeDOM(i); grp = g('kf-g-' + i); }
    var sel = (i === kfIdx);
    var outer = grp.children[0], inner = grp.children[1];
    outer.setAttribute('stroke', sel ? '#4CAF50' : '#aaa');
    outer.setAttribute('stroke-width', sel ? '2.5' : '2');
    inner.setAttribute('display', sel ? 'inline' : 'none');
  }
  var kf = keyframes[kfIdx];
  kfInfo.textContent = 'KF' + (kfIdx+1) + ' (t=' + kf.tempo.toFixed(1) + 's): Zoom ' +
    kf.zoom.toFixed(1) + ' | Blur ' + kf.blur + ' | Pitch ' + kf.rotationX +
    '° Yaw ' + kf.rotationY + '° Roll ' + kf.rotationZ + '° | Tx ' + kf.tx + ' Ty ' + kf.ty;
}

function reconstruirTodosKeyframesDOM() {
  while (kfContainer.firstChild) kfContainer.removeChild(kfContainer.firstChild);
  while (kfLabelContainer.firstChild) kfLabelContainer.removeChild(kfLabelContainer.firstChild);
  for (var i = 0; i < keyframes.length; i++) criarKeyframeDOM(i);
  timeline.syncDuracaoSlider(g('duracaoSlide'), g('lblDuracao'));
}

/* ====== LEITURA / APLICAÇÃO DE SLIDERS ====== */

function lerSliders() {
  var kf = keyframes[kfIdx], el;
  kf.zoom = (el = g('zoomSlide')) ? parseFloat(el.value) : 1.0;
  kf.blur = parseInt((el = g('blurSlide')) ? el.value : 7);
  kf.rotationX = parseInt((el = g('pitchSlide')) ? el.value : 0);
  kf.rotationY = parseInt((el = g('yawSlide')) ? el.value : 0);
  kf.rotationZ = parseInt((el = g('rollSlide')) ? el.value : 0);
  kf.tx = parseInt((el = g('txSlide')) ? el.value : 0);
  kf.ty = parseInt((el = g('tySlide')) ? el.value : 0);
  zoomEnabled = g('chkZoom') ? g('chkZoom').checked : true;
  blurEnabled = g('chkBlur') ? g('chkBlur').checked : true;
  rotEnabled = g('chkRot') ? g('chkRot').checked : true;
  translEnabled = g('chkTransl') ? g('chkTransl').checked : true;
  timeline.setDuracao((el = g('duracaoSlide')) ? parseInt(el.value) : 10);
  for (var i = 1; i < keyframes.length; i++) {
    if (keyframes[i].tempo > timeline.duracao) keyframes[i].tempo = timeline.duracao;
    if (keyframes[i].tempo <= keyframes[i-1].tempo) keyframes[i].tempo = keyframes[i-1].tempo + 0.5;
  }
  aplicarValoresAtuais();
}

function aplicarKeyframeNaCamera(kf) {
  camera.zoom = kf.zoom; camera.blur = kf.blur;
  camera.rotationX = kf.rotationX; camera.rotationY = kf.rotationY; camera.rotationZ = kf.rotationZ;
  camera.tx = kf.tx; camera.ty = kf.ty; camera.perspective = kf.perspective;
  if (camera.blurFilterId) { var fe = document.getElementById(camera.blurFilterId); if (fe) fe.setAttribute('stdDeviation', camera.blur); }
  aplicarTransformacao();
}

function aplicarValoresAtuais() { if (!rodando) { if (!marcacaoAtiva) aplicarKeyframeNaCamera(keyframes[kfIdx]); atualizarHighlights(keyframes[kfIdx].tempo); atualizarStatus(); } }

function atualizarStatus() {
  statusText.textContent =
    'Zoom: ' + camera.zoom.toFixed(2) + 'x  |  Blur: ' + camera.blur.toFixed(1) + 'px  |  ' +
    'Pitch: ' + camera.rotationX.toFixed(1) + '°  Yaw: ' + camera.rotationY.toFixed(1) +
    '°  Roll: ' + camera.rotationZ.toFixed(1) + '°  |  Tx: ' + camera.tx.toFixed(0) + ' Ty: ' + camera.ty.toFixed(0);
}

function atualizarSliderLabels() {
  var el;
  if ((el = g('zoomSlide'))) g('valZoom').value = parseFloat(el.value).toFixed(1);
  if ((el = g('blurSlide'))) g('valBlur').value = parseFloat(el.value);
  if ((el = g('pitchSlide'))) g('valPitch').value = el.value;
  if ((el = g('yawSlide'))) g('valYaw').value = el.value;
  if ((el = g('rollSlide'))) g('valRoll').value = el.value;
  if ((el = g('txSlide'))) g('valTx').value = el.value;
  if ((el = g('tySlide'))) g('valTy').value = el.value;
  timeline.syncDuracaoSlider(g('duracaoSlide'), g('valDuracao'));
}

function carregarSlidersDoKeyframe(kf) {
  g('zoomSlide').value = kf.zoom; g('valZoom').value = kf.zoom.toFixed(1);
  g('blurSlide').value = Math.round(kf.blur); g('valBlur').value = Math.round(kf.blur);
  g('pitchSlide').value = Math.round(kf.rotationX); g('valPitch').value = Math.round(kf.rotationX);
  g('yawSlide').value = Math.round(kf.rotationY); g('valYaw').value = Math.round(kf.rotationY);
  g('rollSlide').value = Math.round(kf.rotationZ); g('valRoll').value = Math.round(kf.rotationZ);
  g('txSlide').value = Math.round(kf.tx); g('valTx').value = Math.round(kf.tx);
  g('tySlide').value = Math.round(kf.ty); g('valTy').value = Math.round(kf.ty);
  atualizarSliderLabels();
}

/* ====== SELEÇÃO E MANIPULAÇÃO DE KEYFRAMES ====== */

function selecionarKF(i) {
  if (rodando) return;
  kfIdx = Math.max(0, Math.min(keyframes.length - 1, i));
  pausadoMs = 0;
  carregarSlidersDoKeyframe(keyframes[kfIdx]);
  atualizarSelecaoKeyframes();
  reposicionarTodosDots();
  aplicarValoresAtuais();
  timeline.syncDuracaoSlider(g('duracaoSlide'), g('lblDuracao'));
}

function addKeyframe() {
  if (rodando) return;
  lerSliders();
  var next = (kfIdx + 1 < keyframes.length) ? keyframes[kfIdx + 1] : null;
  var novo;
  if (next) {
    var seg = next.tempo - keyframes[kfIdx].tempo;
    var t = keyframes[kfIdx].tempo + 0.5;
    if (t >= next.tempo) t = keyframes[kfIdx].tempo + seg / 2;
    var f = seg > 0 ? (t - keyframes[kfIdx].tempo) / seg : 0.5;
    novo = keyframes[kfIdx].lerp(next, f);
    novo.tempo = t;
  } else {
    novo = keyframes[kfIdx].clone();
    novo.tempo = keyframes[kfIdx].tempo + 1;
  }
  keyframes.splice(kfIdx + 1, 0, novo);
  for (var i = kfIdx + 1; i < keyframes.length; i++) {
    removerKeyframeDOM(i);
  }
  for (var i = kfIdx + 1; i < keyframes.length; i++) criarKeyframeDOM(i);
  selecionarKF(kfIdx + 1);
  salvarEstado();
}

function removeKeyframe() {
  if (rodando || keyframes.length <= 2) return;
  lerSliders();
  var removido = kfIdx;
  keyframes.splice(removido, 1);
  for (var i = removido; i <= keyframes.length; i++) removerKeyframeDOM(i);
  for (var i = removido; i < keyframes.length; i++) criarKeyframeDOM(i);
  if (kfIdx >= keyframes.length) kfIdx = keyframes.length - 1;
  selecionarKF(kfIdx);
  salvarEstado();
}

/* ====== HIGHLIGHTS ====== */

function atualizarHighlights(t) {
  var layer = H.get('highlightsLayer');
  while (layer.firstChild) layer.removeChild(layer.firstChild);

  for (var ki = 0; ki < keyframes.length; ki++) {
    var marks = highlighter.getMarks(ki);
    for (var mi = 0; mi < marks.length; mi++) {
      var m = marks[mi], f = highlighter.computeFactor(t, keyframes, ki);
      if (f <= 0) continue;
      var p = document.createElementNS(H.SVG_NS, 'path');
      p.setAttribute('d', m.path);
      p.setAttribute('stroke', m.color);
      p.setAttribute('stroke-width', m.thickness);
      p.setAttribute('fill', 'none');
      p.setAttribute('stroke-linecap', 'round');
      p.setAttribute('stroke-linejoin', 'round');
      p.setAttribute('stroke-dasharray', m.totalLength);
      p.setAttribute('stroke-dashoffset', m.totalLength * (1 - f));
      layer.appendChild(p);
    }
  }
}

/* ====== ANIMAÇÃO ====== */

function animar(timestamp) {
  if (!rodando) return;
  if (inicioTimestamp === null) inicioTimestamp = timestamp;
  var t = pausadoMs / 1000 + (timestamp - inicioTimestamp) / 1000;
  var last = keyframes[keyframes.length - 1];
  t = Math.min(t, last.tempo);

  for (var i = 0; i < keyframes.length - 1; i++) {
    var k0 = keyframes[i], k1 = keyframes[i+1];
    if (t >= k0.tempo && t <= k1.tempo) {
      var seg = k1.tempo - k0.tempo;
      var f = seg > 0 ? (t - k0.tempo) / seg : 1;
      f = H.easeInOut(f);
      var interp = k0.lerp(k1, f);
      if (zoomEnabled) camera.zoom = interp.zoom;
      if (blurEnabled) camera.blur = interp.blur;
      if (rotEnabled) { camera.rotationX = interp.rotationX; camera.rotationY = interp.rotationY; camera.rotationZ = interp.rotationZ; }
      if (translEnabled) { camera.tx = interp.tx; camera.ty = interp.ty; }
      if (camera.blurFilterId) { var fe = document.getElementById(camera.blurFilterId); if (fe) fe.setAttribute('stdDeviation', camera.blur); }
      if (kfIdx !== i) { kfIdx = i; atualizarSelecaoKeyframes(); carregarSlidersDoKeyframe(keyframes[i]); }
      break;
    }
  }

  aplicarTransformacao();
  atualizarHighlights(t);
  atualizarStatus();

  var prog = t / last.tempo;
  var ultX = timeline.kfToScreenX(last.tempo);
  progressBar.setAttribute('width', Math.max(0, Math.min(ultX - T_BAR_X, (ultX - T_BAR_X) * prog)));

  if (t < last.tempo) {
    requestAnimationFrame(animar);
  } else {
    progressBar.setAttribute('width', Math.max(0, ultX - T_BAR_X));
    rodando = false;
    selecionarKF(keyframes.length - 1);
    if (modoExibicao) { H.get('toolbars').setAttribute('display', 'inline'); H.get('modoExibicao').setAttribute('display', 'inline'); }
    aplicarLetterbox();
    if (gravando) { try { mediaRecorder.stop(); gravando = false; } catch(e) {} }
    g('playLabel').textContent = '\u25B6';
    statusBg.setAttribute('fill', 'rgba(0,0,0,0.55)');
    statusText.textContent = 'Animação concluída — ajuste os parâmetros e pressione ▶ PLAY';
    pausadoMs = 0;
  }
}

function iniciar() {
  if (rodando) { pausar(); return; }
  if (marcacaoAtiva) { canetaAtiva = false; sairModoMarcacao(); g('penRow').style.display = 'none'; }
  if (keyframes.length < 2) return;
  if (pausadoMs === 0) {
    lerSliders();
    aplicarKeyframeNaCamera(keyframes[kfIdx]);
    pausadoMs = keyframes[kfIdx].tempo * 1000;
    progressBar.setAttribute('width', '0');
  }
  if (modoExibicao) { H.get('toolbars').setAttribute('display', 'none'); H.get('modoExibicao').setAttribute('display', 'none'); }
  aplicarLetterbox(1);
  inicioTimestamp = null; rodando = true;
  atualizarHighlights(0);
  g('playLabel').textContent = '\u23F8';
  statusBg.setAttribute('fill', 'rgba(76,175,80,0.6)');
  requestAnimationFrame(animar);
}

/* ====== EVENTOS DE MOUSE ====== */

btnPlay.addEventListener('click', iniciar);

H.get('btnUpload').addEventListener('click', function() { var fi = g('fileInput'); if (fi) fi.click(); });

H.get('btnSave').addEventListener('click', function() {
  lerSliders();
  var state = { imagem: imagem.src, modoExibicao: modoExibicao, resolucao: resolucao, duracao: timeline.duracao,
    zoomEnabled: zoomEnabled, blurEnabled: blurEnabled, rotEnabled: rotEnabled, translEnabled: translEnabled, kfs: [],
    highlights: highlighter.toJSON() };
  for (var i = 0; i < keyframes.length; i++) {
    var k = keyframes[i];
    state.kfs.push({ tempo: k.tempo, zoom: k.zoom, blur: k.blur, rotationX: k.rotationX, rotationY: k.rotationY,
      rotationZ: k.rotationZ, tx: k.tx, ty: k.ty, perspective: k.perspective });
  }
  var json = JSON.stringify(state);
  var blob = new Blob([json], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElementNS('http://www.w3.org/1999/xhtml', 'a');
  a.href = url; a.download = 'projeto-animacao.json';
  document.documentElement.appendChild(a); a.click();
  document.documentElement.removeChild(a); URL.revokeObjectURL(url);
  statusText.textContent = 'Projeto salvo como projeto-animacao.json';
  salvarEstado();
});

H.get('btnOpen').addEventListener('click', function() {
  var pi = g('projInput'); if (pi) pi.click();
});

document.addEventListener('change', function(e) {
  if (e.target && e.target.id === 'projInput') {
    var file = e.target.files[0]; if (!file) return;
    var r = new FileReader();
    r.onload = function(ev) {
      try {
        var data = JSON.parse(ev.target.result);
        fetch('/state', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) })
          .then(function() { location.reload(); })
          .catch(function(ex) { statusText.textContent = 'Arquivo inválido: ' + ex.message; });
      } catch(ex) {
        statusText.textContent = 'Arquivo inválido.';
      }
    };
    r.readAsText(file);
  }
});

H.get('btnReset').addEventListener('click', function() {
  if (rodando) return;
  if (!confirm('Apagar todas as configurações e voltar ao padrão?')) return;
  keyframes.length = 0;
  keyframes.push(new KF({ tempo: 0, zoom: 1.0, blur: 7, rotationX: -25, rotationY: 15 }));
  keyframes.push(new KF({ tempo: 5, zoom: 1.5, blur: 0, rotationX: 0, rotationY: 0 }));
  timeline.keyframes = keyframes;
  timeline.setDuracao(10); g('duracaoSlide').value = 10;
  zoomEnabled = true; blurEnabled = true; rotEnabled = true; translEnabled = true;
  g('chkZoom').checked = true; g('chkBlur').checked = true; g('chkRot').checked = true; g('chkTransl').checked = true;
  imagem.src = IMAGEM;
  modoExibicao = false; g('modoExibCheck').textContent = '';
  kfIdx = 0;
  reconstruirTodosKeyframesDOM();
  carregarSlidersDoKeyframe(keyframes[0]);
  atualizarSelecaoKeyframes();
  aplicarValoresAtuais();
  statusText.textContent = 'Configurações resetadas — pressione ▶ PLAY';
  fetch('/state', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
});

var mediaRecorder = null;
var recordedChunks = [];
var gravando = false;

H.get('btnRecord').addEventListener('click', function() {
  if (mediaRecorder) {
    mediaRecorder.stop();
    gravando = false;
    return;
  }

  var displayMediaOptions = { video: { displaySurface: 'browser' }, audio: false };
  try {
    navigator.mediaDevices.getDisplayMedia(displayMediaOptions).then(function(stream) {
      recordedChunks = [];

      try {
        mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
      } catch(e) {
        try {
          mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp8' });
        } catch(e2) {
          mediaRecorder = new MediaRecorder(stream);
        }
      }

      mediaRecorder.ondataavailable = function(e) {
        if (e.data.size > 0) recordedChunks.push(e.data);
      };

      mediaRecorder.onstop = function() {
        try { if (document.fullscreenElement) document.exitFullscreen(); } catch(e) {}
        var webmBlob = new Blob(recordedChunks, { type: 'video/webm' });

        function baixarArquivo(blob, nome) {
          var url = URL.createObjectURL(blob);
          var a = document.createElementNS('http://www.w3.org/1999/xhtml', 'a');
          a.href = url; a.download = nome;
          document.documentElement.appendChild(a); a.click();
          document.documentElement.removeChild(a);
          URL.revokeObjectURL(url);
        }

        function finalizar(msg, blob, nome) {
          stream.getTracks().forEach(function(t) { t.stop(); });
          mediaRecorder = null; gravando = false;
          g('recordLabel').textContent = '\u25CF';
          if (blob) baixarArquivo(blob, nome);
          statusText.textContent = msg;
        }

        statusText.textContent = 'Convertendo para MP4...';
        var form = new FormData();
        form.append('video', webmBlob, 'video.webm');

        var xhrC = new XMLHttpRequest();
        xhrC.open('POST', '/convert?res=' + resolucao, true);
        xhrC.responseType = 'blob';
        xhrC.timeout = 120000;
        xhrC.onload = function() {
          if (xhrC.status === 200) finalizar('MP4 salvo como animacao.mp4', xhrC.response, 'animacao.mp4');
          else finalizar('Conversão falhou — WebM salvo', webmBlob, 'animacao-gravada.webm');
        };
        xhrC.onerror = function() { finalizar('Servidor offline — WebM salvo', webmBlob, 'animacao-gravada.webm'); };
        xhrC.ontimeout = function() { finalizar('Conversão demorou — WebM salvo', webmBlob, 'animacao-gravada.webm'); };
        xhrC.send(webmBlob);
      };

      mediaRecorder.start();
      gravando = true;
      g('recordLabel').textContent = '\u25A0';
      statusText.textContent = 'Gravando...';

      try { document.documentElement.requestFullscreen(); } catch(e) {}
      iniciar();
    }).catch(function(err) {
      statusText.textContent = 'Gravação cancelada ou não permitida.';
    });
  } catch(e) {
    statusText.textContent = 'Seu navegador não suporta gravação de tela. Use Chrome ou Edge.';
  }
});

document.addEventListener('change', function(e) {
  if (e.target && e.target.id === 'fileInput') {
    var file = e.target.files[0]; if (!file) return;
    var ext = file.name.split('.').pop() || 'jpg';
    fetch('/upload?ext=' + encodeURIComponent(ext), { method: 'POST', body: file })
      .then(function() {
        imagem.src = '/uploads/image.' + ext;
        statusText.textContent = 'Imagem carregada: ' + file.name;
        salvarEstado();
      })
      .catch(function(err) { statusText.textContent = 'Erro no upload: ' + err.message; });
  }
});

document.addEventListener('mousedown', function(e) {
  if (canetaAtiva && e.button === 2) e.preventDefault();
});

document.addEventListener('contextmenu', function(e) {
  if (canetaAtiva) e.preventDefault();
});

document.addEventListener('keydown', function(e) {
  var a = document.activeElement; if (a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA')) return;
  if (e.code === 'Home') { e.preventDefault(); if (!rodando) selecionarKF(0); }
  if (e.code === 'End') { e.preventDefault(); if (!rodando) selecionarKF(keyframes.length - 1); }
  if (e.code === 'ArrowLeft') { e.preventDefault(); if (!rodando) { if (kfIdx > 0) selecionarKF(kfIdx - 1); } }
  if (e.code === 'ArrowRight') { e.preventDefault(); if (!rodando) { if (kfIdx < keyframes.length - 1) selecionarKF(kfIdx + 1); } }
  if (e.code === 'Space') { e.preventDefault(); iniciar(); }
  if (e.code === 'Tab') { e.preventDefault(); if (marcacaoAtiva && !modoBorracha) toggleCamadas(); }
});

H.get('overlayMouse').addEventListener('mouseenter', function(e) {
  if (marcacaoAtiva) g('penCursor').setAttribute('display', 'inline');
});

H.get('overlayMouse').addEventListener('mouseleave', function(e) {
  if (marcacaoAtiva) g('penCursor').setAttribute('display', 'none');
});

H.get('overlayMouse').addEventListener('mousedown', function(e) {
  if (rodando) return;

  if (canetaAtiva) {
    if (e.button === 2) {
      e.preventDefault();
      arrastando = true; mouseIniX = e.clientX; mouseIniY = e.clientY;
      lerSliders(); txAnchor = keyframes[kfIdx].tx; tyAnchor = keyframes[kfIdx].ty;
      return;
    }

    var rect = H.get('svgRaiz').getBoundingClientRect();
    var scaleX = 800 / rect.width, scaleY = 500 / rect.height;
    var svgX = (e.clientX - rect.left) * scaleX, svgY = (e.clientY - rect.top) * scaleY;
    if (svgX < 0 || svgX > 800 || svgY < 0 || svgY > 500) return;

    if (modoBorracha) {
      var marks = highlighter.getMarks(kfIdx);
      var hit = -1;
      var distThreshold = 8;
      for (var mi = marks.length - 1; mi >= 0; mi--) {
        var testP = document.createElementNS(H.SVG_NS, 'path');
        testP.setAttribute('d', marks[mi].path);
        H.get('svgRaiz').appendChild(testP);
        var len = testP.getTotalLength();
        for (var li = 0; li < len; li += 6) {
          var pt = testP.getPointAtLength(li);
          var dx = svgX - pt.x, dy = svgY - pt.y;
          if (dx * dx + dy * dy < distThreshold * distThreshold) { hit = mi; break; }
        }
        testP.parentNode.removeChild(testP);
        if (hit >= 0) break;
      }
      if (hit >= 0) {
        marks.splice(hit, 1);
        aplicarValoresAtuais();
        salvarEstado();
      }
      return;
    }

    drawingPath = 'M' + svgX.toFixed(1) + ',' + svgY.toFixed(1);
    drawingPoints = [{x: svgX, y: svgY}];

    var prev = H.get('drawingPreview');
    if (prev) prev.parentNode.removeChild(prev);
    var p = document.createElementNS(H.SVG_NS, 'path');
    p.setAttribute('id', 'drawingPreview');
    p.setAttribute('d', drawingPath);
    p.setAttribute('stroke', corCanetaRGBA(0.5));
    p.setAttribute('stroke-width', canetaThickness);
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
    H.get('highlightsLayer').appendChild(p);
    return;
  }

  arrastando = true; mouseIniX = e.clientX; mouseIniY = e.clientY;
  lerSliders(); txAnchor = keyframes[kfIdx].tx; tyAnchor = keyframes[kfIdx].ty;
});

window.addEventListener('mousemove', function(e) {
  if (draggingPanel) {
    var dy = e.clientY - panelAnchorY;
    var fo = document.querySelector('foreignObject');
    var tl = g('timelineGroup');
    if (fo && tl) {
      var newY = Math.max(-100, Math.min(480, parseInt(fo.getAttribute('y')) + dy));
      fo.setAttribute('y', newY);
      tl.setAttribute('transform', 'translate(0,' + (newY - 390 + 5) + ')');
      g('panelHandle').setAttribute('y', newY - 5);
    }
    panelAnchorY = e.clientY;
    return;
  }

  if (canetaAtiva && !rodando) {
    var rect = H.get('svgRaiz').getBoundingClientRect();
    var scaleX = 800 / rect.width, scaleY = 500 / rect.height;
    var sx = (e.clientX - rect.left) * scaleX, sy = (e.clientY - rect.top) * scaleY;
    var pc = g('penCursor');
    pc.setAttribute('cx', sx); pc.setAttribute('cy', sy);
    pc.setAttribute('display', (sx>=0&&sx<=800&&sy>=0&&sy<=500) ? 'inline' : 'none');

    if (drawingPath && sx>=0 && sx<=800 && sy>=0 && sy<=500) {
      drawingPath += ' L' + sx.toFixed(1) + ',' + sy.toFixed(1);
      drawingPoints.push({x: sx, y: sy});
      var dp = g('drawingPreview');
      if (dp) dp.setAttribute('d', drawingPath);
    }
    return;
  }

  if (draggingKF && !rodando) {
    var rect = H.get('svgRaiz').getBoundingClientRect();
    var scale = 800 / rect.width, dx = (e.clientX - dragAnchorX) * scale;
    var raw = dragAnchorTime + (dx / T_BAR_W) * Math.max(keyframes[keyframes.length-1].tempo, timeline.duracao);
    raw = Math.max(0.5, Math.min(timeline.duracao, raw));
    var next = (dragKFIndex + 1 < keyframes.length) ? keyframes[dragKFIndex+1].tempo : timeline.duracao;
    var prev = keyframes[dragKFIndex-1].tempo;
    raw = Math.max(prev + 0.5, Math.min(next - 0.1, raw));
    keyframes[dragKFIndex].tempo = raw;
    moverKeyframeDOM(dragKFIndex, timeline.kfToScreenX(raw));
    var lbl = g('kf-lbl-' + dragKFIndex); if (lbl) lbl.textContent = raw.toFixed(1) + 's';
    aplicarValoresAtuais(); return;
  }
  if (!arrastando || rodando) return;
  var dx = e.clientX - mouseIniX, dy = e.clientY - mouseIniY;
  var ntx = Math.round(Math.max(-300, Math.min(300, txAnchor + dx)));
  var nty = Math.round(Math.max(-300, Math.min(300, tyAnchor + dy)));
  keyframes[kfIdx].tx = ntx; keyframes[kfIdx].ty = nty;
  g('txSlide').value = ntx; g('tySlide').value = nty;
  atualizarSliderLabels(); aplicarValoresAtuais(); salvarEstado();
});

window.addEventListener('mouseup', function(e) {
  if (draggingPanel) { draggingPanel = false; return; }
  if (drawingPath) {
    var dp = g('drawingPreview');
    var totalL = dp ? dp.getTotalLength() : drawingPath.length * 2;
    highlighter.addMark(kfIdx, drawingPath, canetaThickness, totalL, corCanetaRGBA());
    drawingPath = ''; drawingPoints = [];
    if (dp) dp.parentNode.removeChild(dp);
    g('penCursor').setAttribute('display', 'none');
    aplicarValoresAtuais();
    salvarEstado();
    return;
  }
  arrastando = false;
  if (draggingKF) { draggingKF = false; dragKFIndex = -1; selecionarKF(kfIdx); salvarEstado(); }
});

H.get('overlayMouse').addEventListener('wheel', function(e) {
  if (rodando || !e.ctrlKey) return; e.preventDefault();
  var d = e.deltaY < 0 ? 1 : -1;
  keyframes[kfIdx].zoom = Math.max(0.1, keyframes[kfIdx].zoom + d * 0.1);
  g('zoomSlide').value = keyframes[kfIdx].zoom;
  atualizarSliderLabels(); aplicarValoresAtuais(); salvarEstado();
});

function salvarEstado() {
  if (restaurando) return;
  try {
    var state = { imagem: imagem.src, modoExibicao: modoExibicao, resolucao: resolucao, duracao: timeline.duracao,
      zoomEnabled: zoomEnabled, blurEnabled: blurEnabled, rotEnabled: rotEnabled, translEnabled: translEnabled, kfs: [],
      highlights: highlighter.toJSON() };
    for (var i = 0; i < keyframes.length; i++) {
      var k = keyframes[i];
      state.kfs.push({ tempo: k.tempo, zoom: k.zoom, blur: k.blur, rotationX: k.rotationX, rotationY: k.rotationY,
        rotationZ: k.rotationZ, tx: k.tx, ty: k.ty, perspective: k.perspective });
    }
    fetch('/state', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(state) })
      .catch(function(e) { statusText.textContent = 'Erro ao salvar: ' + e.message; });
  } catch(e) { statusText.textContent = 'Erro ao salvar: ' + e.message; }
}

function aplicarEstado(st) {
  if (!st) return;
  try {
    if (st.imagem) imagem.src = st.imagem;
    if (st.modoExibicao !== undefined) { modoExibicao = st.modoExibicao; g('modoExibCheck').textContent = modoExibicao ? '\u2713' : ''; }
    if (st.duracao !== undefined) { timeline.duracao = st.duracao; g('duracaoSlide').value = timeline.duracao; }
    if (st.resolucao !== undefined) { resolucao = st.resolucao; g('selResolucao').value = resolucao; }
    if (st.highlights !== undefined) highlighter.fromJSON(st.highlights);
    if (st.zoomEnabled !== undefined) zoomEnabled = st.zoomEnabled;
    if (st.blurEnabled !== undefined) blurEnabled = st.blurEnabled;
    if (st.rotEnabled !== undefined) rotEnabled = st.rotEnabled;
    if (st.translEnabled !== undefined) translEnabled = st.translEnabled;
    if (st.kfs && st.kfs.length >= 2) {
      keyframes.length = 0;
      for (var i = 0; i < st.kfs.length; i++) keyframes.push(new KF(st.kfs[i]));
      timeline.keyframes = keyframes;
    }
  } catch(e) { statusText.textContent = 'Erro ao carregar estado: ' + e.message; }
}

function reposicionarTodosDots() {
  for (var j = 0; j < keyframes.length; j++) {
    moverKeyframeDOM(j, timeline.kfToScreenX(keyframes[j].tempo));
    var lbl = g('kf-lbl-' + j); if (lbl) lbl.textContent = (j===0 ? '0.0s' : keyframes[j].tempo.toFixed(1) + 's');
  }
}

function setupSliderListeners() {
  var sls = document.querySelectorAll('input[type=range], input[type=checkbox]');
  for (var i = 0; i < sls.length; i++) {
    sls[i].addEventListener('input', function() { lerSliders(); atualizarSliderLabels(); atualizarSelecaoKeyframes(); reposicionarTodosDots(); salvarEstado(); });
  }
  var nums = document.querySelectorAll('#valZoom,#valBlur,#valPitch,#valYaw,#valRoll,#valTx,#valTy,#valDuracao');
  for (var j = 0; j < nums.length; j++) {
    nums[j].addEventListener('input', function() {
      var idMap = { valZoom:'zoomSlide', valBlur:'blurSlide', valPitch:'pitchSlide', valYaw:'yawSlide', valRoll:'rollSlide', valTx:'txSlide', valTy:'tySlide', valDuracao:'duracaoSlide' };
      var sliderId = idMap[this.id];
      if (sliderId) { var s = g(sliderId); if (s) s.value = this.value; }
      lerSliders(); atualizarSliderLabels(); atualizarSelecaoKeyframes(); reposicionarTodosDots(); salvarEstado();
    });
  }
  g('btnAddKF').addEventListener('click', addKeyframe);
  g('btnDelKF').addEventListener('click', removeKeyframe);

  g('panelHandle').addEventListener('mousedown', function(e) {
    e.preventDefault(); e.stopPropagation();
    draggingPanel = true;
    panelAnchorY = e.clientY;
  });

  g('btnPen').addEventListener('click', function() {
    canetaAtiva = !canetaAtiva;
    modoBorracha = false;
    var er = g('btnEraser');
    er.children[0].setAttribute('fill', '#555');
    er.children[0].setAttribute('stroke', '#777');
    var btn = g('btnPen');
    if (canetaAtiva) {
      btn.children[0].setAttribute('fill', '#4CAF50');
      btn.children[0].setAttribute('stroke', '#388E3C');
      btn.children[1].setAttribute('fill', '#fff');
      entrarModoMarcacao();
      atualizarPenCursorColor();
    } else {
      btn.children[0].setAttribute('fill', '#555');
      btn.children[0].setAttribute('stroke', '#777');
      btn.children[1].setAttribute('fill', '#ccc');
      sairModoMarcacao();
    }
    g('penRow').style.display = canetaAtiva ? 'flex' : 'none';
  });

  g('penThickness').addEventListener('input', function() {
    canetaThickness = parseFloat(this.value);
    g('lblPenThickness').textContent = canetaThickness;
    g('penCursor').setAttribute('r', canetaThickness / 2);
  });

  g('penColor').addEventListener('input', function() {
    canetaColor = this.value;
    atualizarPenCursorColor();
  });

  g('penOpacity').addEventListener('input', function() {
    canetaOpacity = parseInt(this.value) / 100;
    g('lblPenOpacity').textContent = canetaOpacity.toFixed(2);
    atualizarPenCursorColor();
  });

  g('btnEraser').addEventListener('click', function() {
    if (!canetaAtiva) { g('btnPen').dispatchEvent(new Event('click')); }
    modoBorracha = !modoBorracha;
    var er = g('btnEraser');
    if (modoBorracha) {
      er.children[0].setAttribute('fill', '#F44336');
      er.children[0].setAttribute('stroke', '#C62828');
      er.children[1].setAttribute('fill', '#fff');
    } else {
      er.children[0].setAttribute('fill', '#555');
      er.children[0].setAttribute('stroke', '#777');
      er.children[1].setAttribute('fill', '#fff');
    }
    atualizarPenCursorColor();
  });
  g('selResolucao').addEventListener('change', function() {
    resolucao = this.value;
    aplicarLetterbox();
    salvarEstado();
  });
}

var panelReady = false;
function initQuandoPronto() {
  if (panelReady) return; if (!g('zoomSlide')) return;
  panelReady = true;
  restaurando = true;
  fetch('/state')
    .then(function(r) { return r.json(); })
    .then(function(st) { if (st && st.imagem) aplicarEstado(st); })
    .catch(function() {})
    .then(function() {
      setupSliderListeners();
      g('chkZoom').checked = zoomEnabled; g('chkBlur').checked = blurEnabled;
      g('chkRot').checked = rotEnabled; g('chkTransl').checked = translEnabled;
      carregarSlidersDoKeyframe(keyframes[0]);
      reconstruirTodosKeyframesDOM();
      kfIdx = 0;
      atualizarSelecaoKeyframes(); aplicarValoresAtuais();
      aplicarLetterbox();
      restaurando = false;

      H.get('modoExibicao').addEventListener('click', function() {
        modoExibicao = !modoExibicao;
        g('modoExibCheck').textContent = modoExibicao ? '\u2713' : '';
        salvarEstado();
      });
    });
}
setTimeout(initQuandoPronto, 200);
var poll = setInterval(function() { if (!panelReady) initQuandoPronto(); else clearInterval(poll); }, 100);

aplicarKeyframeNaCamera(keyframes[0]);
atualizarStatus();

div.style:
font-family: Arial, sans-serif; font-size: 11px; color: #eee;
background: rgba(20,20,20,0.85); padding: 4px 8px;
box-sizing: border-box; width: 800px; user-select: none; overflow: visible;
